def is_valid_date(year, month, day):
    if year < 1:
        return False
    if month < 1 or month > 12:
        return False

    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    dim = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    return 1 <= day <= dim[month - 1]

def weekday_sakamoto(year, month, day):
    t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
    y = year
    if month < 3:
        y -= 1
    return (y + y // 4 - y // 100 + y // 400 + t[month - 1] + day) % 7

def quarter_of_month(month_index):
    m = (month_index - 1) % 12 + 1
    return (m - 1) // 3 + 1

def quarter_of_date(year, month, day):
    quarter = (month - 1) // 3 + 1
    first_month = (quarter - 1) * 3 + 1
    return (quarter, first_month)

def days_remaining_in_month(year, month, day):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    dim = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
