def days_remaining_in_year(year, month, day):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    leap = is_leap(year)
    doy = sum(days_in_month[:month - 1])
    if leap and month > 2:
        doy += 1
    doy += day
    total = 366 if leap else 365
    return total - doy

def minutes_since_midnight(time_str):
    h, m = time_str.split(':')
    return int(h) * 60 + int(m)
